# Let's look for readable strings in the binary, especially looking for password-like patterns
target = "{TARGET}"

with open(target, 'rb') as f:
    data = f.read()

# Extract all printable strings (minimum 4 characters)
def extract_strings(data, min_len=6):
    strings = []
    current = b''
    start = 0
    for i, b in enumerate(data):
        if 32 <= b < 127:
            if not current:
                start = i
            current += bytes([b])
        else:
            if len(current) >= min_len:
                strings.append((start, current.decode('ascii', errors='replace')))
            current = b''
    if len(current) >= min_len:
        strings.append((start, current.decode('ascii', errors='replace')))
    return strings

strings = extract_strings(data, 8)
# Look for interesting patterns
print("=== Potentially interesting strings ===")
for offset, s in strings:
    s_lower = s.lower()
    if any(x in s_lower for x in ['pass', 'secret', 'key', 'flag', 'check', 'valid', 'correct', 'wrong', 'fail', 'success']):
        print(f"0x{offset:x}: {s}")

# Also look for patterns that look like keys/passwords
print("\n=== All strings 8-32 chars that look like passwords ===")
import re
for offset, s in strings:
    if 8 <= len(s) <= 40:
        # Look for alphanumeric strings that could be passwords
        if re.match(r'^[a-zA-Z0-9_\-]+$', s) and not s.startswith('/') and not s.startswith('lib'):
            print(f"0x{offset:x}: {s[:60]}")
